pub struct Inflector;

impl Inflector {
    pub fn initialize() {}

    pub fn pluralize(word: &str) -> String {
        let mut output = String::with_capacity(word.len() + 1);
        output.push_str(word);
        output.push('s');
        output
    }

    pub fn camelize(word: &str) -> String {
        let mut output = Vec::with_capacity(word.len());
        let mut uppercase_next = false;

        for &byte in word.as_bytes() {
            if byte == b'_' {
                uppercase_next = true;
                continue;
            }

            if uppercase_next {
                output.push(byte.to_ascii_uppercase());
                uppercase_next = false;
            } else {
                output.push(byte);
            }
        }

        String::from_utf8(output).expect("camelize preserves UTF-8 for ASCII-compatible input")
    }

    pub fn underscore(word: &str) -> String {
        let bytes = word.as_bytes();
        let mut output = Vec::with_capacity(bytes.len() * 2);

        for (index, &byte) in bytes.iter().enumerate() {
            if byte.is_ascii_uppercase() {
                if index != 0 {
                    output.push(b'_');
                }
                output.push(byte.to_ascii_lowercase());
            } else {
                output.push(byte);
            }
        }

        String::from_utf8(output).expect("underscore preserves UTF-8 for ASCII-compatible input")
    }

    pub fn is_plural(word: &str) -> bool {
        matches!(word.as_bytes().last(), Some(b's'))
    }

    pub fn is_singular(word: &str) -> bool {
        !Self::is_plural(word)
    }

    pub fn demodulize(name: &str) -> String {
        let bytes = name.as_bytes();
        let start = bytes
            .windows(2)
            .rposition(|window| window == b"::")
            .map(|index| index + 3)
            .unwrap_or(2);

        if start > bytes.len() {
            panic!("demodulize start index is out of range");
        }

        String::from_utf8(bytes[start..].to_vec())
            .expect("demodulize preserves UTF-8 for ASCII-compatible input")
    }
}

